create extension if not exists pgcrypto;
create table organizations(id uuid primary key default gen_random_uuid(),name text not null,contact_email text,contact_phone text,logo_url text,status text default 'active',created_at timestamptz default now());
create table profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in('super_admin','admin_staff','organization','org_staff','instructor','student')),full_name text not null,email text unique not null,avatar_url text,phone text,organization_id uuid references organizations(id),status text default 'active' check(status in('active','suspended','pending')),created_at timestamptz default now(),updated_at timestamptz default now());
create table admin_permissions(id uuid primary key default gen_random_uuid(),admin_staff_id uuid references profiles(id) on delete cascade,module text not null,can_view boolean default false,can_create boolean default false,can_edit boolean default false,can_delete boolean default false,unique(admin_staff_id,module));
create or replace function app_role() returns text language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid()$$;
create or replace function app_org() returns uuid language sql stable security definer set search_path=public as $$select organization_id from profiles where id=auth.uid()$$;
create table schools(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,created_at timestamptz default now());
create table categories(id uuid primary key default gen_random_uuid(),school_id uuid references schools(id),name text not null,slug text unique not null);
create table courses(id uuid primary key default gen_random_uuid(),school_id uuid references schools(id),category_id uuid references categories(id),instructor_id uuid references profiles(id),title text not null,slug text unique not null,description text,thumbnail_url text,level text check(level in('beginner','intermediate','advanced')),duration_weeks int,status text default 'draft' check(status in('draft','published','archived')),created_at timestamptz default now(),updated_at timestamptz default now());
create table course_modules(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id) on delete cascade,title text not null,position int not null);
create table lessons(id uuid primary key default gen_random_uuid(),module_id uuid references course_modules(id) on delete cascade,title text not null,content_type text check(content_type in('video','document','text','link')),content_url text,position int not null,duration_minutes int);
alter table organizations enable row level security;alter table profiles enable row level security;alter table admin_permissions enable row level security;alter table schools enable row level security;alter table categories enable row level security;alter table courses enable row level security;alter table course_modules enable row level security;alter table lessons enable row level security;
create policy org_read on organizations for select using(app_role() in('super_admin','admin_staff') or id=app_org());create policy org_admin on organizations for all using(app_role()='super_admin') with check(app_role()='super_admin');
create policy profile_read on profiles for select using(id=auth.uid() or app_role()='super_admin' or (organization_id=app_org() and app_role() in('organization','org_staff')));create policy profile_self_update on profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy permissions_owner on admin_permissions for select using(admin_staff_id=auth.uid() or app_role()='super_admin');create policy permissions_admin on admin_permissions for all using(app_role()='super_admin') with check(app_role()='super_admin');
create policy school_public on schools for select using(true);create policy category_public on categories for select using(true);create policy course_public on courses for select using(status='published' or app_role() in('super_admin','admin_staff') or instructor_id=auth.uid());
create policy school_admin on schools for all using(app_role() in('super_admin','admin_staff')) with check(app_role() in('super_admin','admin_staff'));create policy category_admin on categories for all using(app_role() in('super_admin','admin_staff')) with check(app_role() in('super_admin','admin_staff'));
create policy course_manage on courses for all using(app_role() in('super_admin','admin_staff') or instructor_id=auth.uid()) with check(app_role() in('super_admin','admin_staff') or instructor_id=auth.uid());
create policy module_read on course_modules for select using(exists(select 1 from courses c where c.id=course_id and(c.status='published' or c.instructor_id=auth.uid() or app_role() in('super_admin','admin_staff'))));create policy module_manage on course_modules for all using(exists(select 1 from courses c where c.id=course_id and(c.instructor_id=auth.uid() or app_role() in('super_admin','admin_staff'))));
create policy lesson_read on lessons for select using(exists(select 1 from course_modules m join courses c on c.id=m.course_id where m.id=module_id and(c.status='published' or c.instructor_id=auth.uid() or app_role() in('super_admin','admin_staff'))));create policy lesson_manage on lessons for all using(exists(select 1 from course_modules m join courses c on c.id=m.course_id where m.id=module_id and(c.instructor_id=auth.uid() or app_role() in('super_admin','admin_staff'))));
